    #[test]
    fn claimed_definition_digest_detects_a_tampered_object_set() {
        let descriptor = r#"{"kind":"Customer","namespace":"sales"}"#;
        let isolated = IsolatedProcessSpec {
            engine: "duckdb_sql".into(),
            runtime_image: String::new(),
            inputs: vec![
                TransformInput {
                    alias: "orders".into(),
                    dataset_id: "orders".into(),
                    object_set: String::new(),
                },
                TransformInput {
                    alias: "customers".into(),
                    dataset_id: String::new(),
                    object_set: descriptor.into(),
                },
            ],
            requires: BTreeMap::from([(
                OBJECT_SET_INPUT_LABEL.into(),
                OBJECT_SET_INPUT_LABEL_VALUE.into(),
            )]),
            code: String::new(),
        };
        let spec = isolated_job_spec("ops", "iso1", "out", isolated);
        let mut claimed = transform("duckdb_sql", "SELECT 1");
        claimed.namespace = "ops".into();
        claimed.transform_id = "iso1".into();
        claimed.output_dataset_id = "out".into();
        claimed.engine = "duckdb_sql".into();
        claimed.definition_digest = spec.definition_digest.clone();
        claimed.inputs = vec![
            sekai_client::protocol::sekai::TransformInput {
                alias: "orders".into(),
                dataset_id: "orders".into(),
                object_set: String::new(),
            },
            sekai_client::protocol::sekai::TransformInput {
                alias: "customers".into(),
                dataset_id: String::new(),
                object_set: descriptor.into(),
            },
        ];
        claimed.requires = vec![sekai_client::protocol::sekai::TransformLabel {
            key: OBJECT_SET_INPUT_LABEL.into(),
            value: OBJECT_SET_INPUT_LABEL_VALUE.into(),
        }];
        verify_claimed_definition(&claimed).expect("matching envelope");
        claimed.inputs[1].object_set = r#"{"kind":"Other","namespace":"sales"}"#.into();
        let error = verify_claimed_definition(&claimed).unwrap_err();
        assert!(
            matches!(error, SekaiSourceError::Transport(ref message) if message.contains("does not match")),
            "{error}"
        );
    }

