    fn snapshot_symlink_is_replaced_not_followed() {
        let scratch = tempfile::tempdir().unwrap();
        let target = scratch.path().join("secret");
        fs::write(&target, "secret\n").unwrap();
        std::os::unix::fs::symlink(&target, scratch.path().join("in.csv")).unwrap();
        let rows = [TransformRunInputRow {
            alias: "in".into(),
            dataset_id: "in".into(),
            row_id: 1,
            values: [("id".into(), "1".into())].into_iter().collect(),
            ..Default::default()
        }];
        let inputs = stage_input_rows(scratch.path(), &rows).expect("staged");
        assert_eq!(fs::read_to_string(&target).unwrap(), "secret\n");
        assert_eq!(fs::read_to_string(&inputs[0].path).unwrap(), "id\n1\n");
        assert!(
            !fs::symlink_metadata(&inputs[0].path)
                .unwrap()
                .file_type()
                .is_symlink()
        );
    }

    #[test]
    fn quoted_multiline_csv_round_trips_on_write_back() {
        let scratch = tempfile::tempdir().unwrap();
        let rows = [TransformRunInputRow {
            alias: "in".into(),
            dataset_id: "in".into(),
            row_id: 1,
            values: [
                ("id".into(), "1".into()),
                ("message".into(), "hello\nworld".into()),
            ]
            .into_iter()
            .collect(),
            ..Default::default()
        }];
        let inputs = stage_input_rows(scratch.path(), &rows).expect("staged");
        let job = job_from_claimed(&work(), &transform("python", "print('ok')"), Vec::new())
            .expect("mapped");
        let write = transform_write_from_complete(
            &[Output {
                name: "in".into(),
                path: inputs[0].path.clone(),
                digest: Digest("sha256:out".into()),
            }],
            &receipt_for(&job, "sha256:out"),
        )
        .expect("mapped write");
        assert_eq!(write.rows.len(), 1);
        assert_eq!(
            write.rows[0].values.get("message").map(String::as_str),
            Some("hello\nworld")
        );
    }

    #[ignore = "needs a local Sekai plane; set KAKO_SEKAI_TARGET, KAKO_SEKAI_NAMESPACE. Proto code is used when present; else set KAKO_SEKAI_CODE. Optional: KAKO_SEKAI_PRINCIPAL, KAKO_SEKAI_TOKEN, KAKO_SEKAI_ALLOW_INSECURE=1. The plane must expose one claimable isolated_process transform: a join and aggregate over two datasets (duckdb_sql or mizuchi)."]
    #[test]
    fn live_plane_stages_two_claim_scoped_inputs() {
        let scratch = tempfile::tempdir().unwrap();
        let mut transport =
            LiveClaimTransport::connect_from_env(scratch.path().to_path_buf()).unwrap();
        let claimed = transport
            .claim_next("kako-live")
            .unwrap()
            .expect("claimable isolated-process work");
        assert!(
            claimed.job.inputs.len() >= 2,
            "join+agg needs two datasets, got {}",
            claimed.job.inputs.len()
        );
        for input in &claimed.job.inputs {
            assert!(input.path.is_file(), "{}", input.path.display());
        }
    }

    #[ignore = "needs a local Sekai plane; set KAKO_SEKAI_TARGET, KAKO_SEKAI_NAMESPACE. Proto code is used when present; else set KAKO_SEKAI_CODE. Optional: KAKO_SEKAI_PRINCIPAL, KAKO_SEKAI_TOKEN, KAKO_SEKAI_ALLOW_INSECURE=1. The plane must expose one claimable isolated_process transform with a dataset input and an object-set input."]
    #[test]
    fn live_plane_stages_object_set_beside_dataset() {
        let scratch = tempfile::tempdir().unwrap();
        let mut transport =
            LiveClaimTransport::connect_from_env(scratch.path().to_path_buf()).unwrap();
        let claimed = transport
            .claim_next("kako-live")
            .unwrap()
            .expect("claimable isolated-process work");
        assert!(
            claimed
                .job
                .inputs
                .iter()
                .any(|input| !input.object_set.is_empty()),
            "expected an object-set input"
        );
        assert!(
            claimed
                .job
                .inputs
                .iter()
                .any(|input| input.object_set.is_empty()),
            "expected a dataset input"
        );
        for input in &claimed.job.inputs {
            assert!(input.path.is_file(), "{}", input.path.display());
        }
    }

    #[ignore = "needs a local Sekai plane; set KAKO_SEKAI_TARGET, KAKO_SEKAI_NAMESPACE. Proto code is used when present; else set KAKO_SEKAI_CODE. Optional: KAKO_SEKAI_PRINCIPAL, KAKO_SEKAI_TOKEN, KAKO_SEKAI_ALLOW_INSECURE=1. The plane must expose one claimable isolated_process transform: a join and aggregate over two datasets (duckdb_sql or mizuchi)."]
    #[test]
    fn live_stale_fence_write_back_is_refused() {
        let scratch = tempfile::tempdir().unwrap();
        let mut transport =
            LiveClaimTransport::connect_from_env(scratch.path().to_path_buf()).unwrap();
        let claimed = transport
            .claim_next("kako-live")
            .unwrap()
            .expect("claimable isolated-process work");
        let credential = transport
            .mint_credential(&claimed.fence, &claimed.job, Duration::from_secs(30))
            .unwrap();
        let mut stale = claimed.fence.clone();
        stale.fencing_token = "stale-fence".into();
        let error = transport
            .write_outputs(
                &stale,
                &credential,
                &[],
                &receipt_for(&claimed.job, "sha256:none"),
            )
            .unwrap_err();
        assert_eq!(error, SekaiSourceError::FenceLost);
        assert!(transport.last_receipt().is_none());
    }
